//! Black-box parity with openEMS for the "advanced physics" features:
//! ems runs the committed fixture models (`tests/fixtures/openems/adv_*`,
//! regenerated by `scripts/openems-oracle/gen-adv.sh`, never by the test
//! suite) and its probe signals are compared with openEMS's.
//!
//! Every case fixes `TimeStep` in the XML (openEMS's default time-step
//! rule is not ems's, see design §5.4), so both codes step with the same
//! `dt` and sample at the same times. Tolerances are a few times the
//! measured agreement (typically 1e-6, the `f32` round-off of the fields
//! and the 12-digit probe files) to absorb last-bit differences of a fresh
//! openEMS build; the numbers are in each test's doc comment.

#[path = "common/oe_probe.rs"]
mod oe_probe;

use ems::{CompileOptions, Results, Simulation};
use oe_probe::{OeProbe, fixture_dir, meta, meta_dt, rel_l2};

/// Runs fixture `name` in ems and checks the time step against the one
/// openEMS reported.
fn run(name: &str, opts: &CompileOptions) -> Results {
    let path = fixture_dir(name).join("model.xml");
    let doc = csx::OpenEmsDocument::read_file(&path).expect("fixture model");
    let mut sim = Simulation::from_document_with(&doc, opts, |f| f.threads(2)).expect("compile");
    let res = sim.run().expect("run");
    let dt = meta_dt(name);
    assert!(
        (res.dt() / dt - 1.0).abs() < 1e-5,
        "{name}: ems dt {:e} vs openEMS {dt:e}",
        res.dt()
    );
    res
}

/// Relative L2 difference of every kept probe of `name` (scalar probes).
fn compare(name: &str, res: &Results) -> Vec<(String, f64)> {
    let mut out = Vec::new();
    for f in meta(name, "keep")[0].split_whitespace() {
        let oe = OeProbe::read(fixture_dir(name).join(f));
        let p = res
            .probe(f)
            .unwrap_or_else(|| panic!("{name}: no ems probe {f}"));
        let (e, dt_off) = rel_l2(&oe.t, oe.values(), p.times(), p.scalar().unwrap(), res.dt());
        assert!(
            dt_off < 1e-3,
            "{name}/{f}: sample times differ by {dt_off} dt"
        );
        eprintln!("{name}/{f}: relative L2 {e:.2e}");
        out.push((f.to_string(), e));
    }
    out
}

fn check(name: &str, tol: f64) {
    let res = run(name, &CompileOptions::default());
    for (f, e) in compare(name, &res) {
        assert!(e < tol, "{name}/{f}: relative L2 {e:.3e} > {tol:e}");
    }
}

// ------------------------------------------------------------ dispersive

// TEM parallel-plate line (PEC z walls, PMC y walls) of 100 × 2 × 2 cells
// of 1 mm, a soft Ez plane source at x = 10 mm, a dispersive slab on
// 30 ≤ x ≤ 70 mm (faces on mesh lines), voltage probes at x = 20, 50,
// 80 mm, 1.8 ps time step. Measured agreement ~1.5e-6 for every case.

/// Debye slab (`Epsilon = 2`, `EpsilonDelta_1 = 3`, `τ = 30 ps`).
#[test]
fn debye_slab() {
    check("adv_debye_slab", 2e-5);
}

/// Drude slab (`Epsilon = 1.5`, `f_plasma = 3 GHz`, `τ = 0.2 ns`):
/// explicit leapfrog scheme, full poles on the interface edges with the
/// edge's averaged `ε∞` (trapezoidal scheme: 2.4e-2 off).
#[test]
fn drude_slab() {
    check("adv_drude_slab", 2e-5);
}

/// Lossy Lorentz slab (`Epsilon = 2`, `f_p = 5 GHz`, `f_Lor = 7 GHz`,
/// `τ = 1 ns`, resonance in the band).
#[test]
fn lorentz_slab() {
    check("adv_lorentz_slab", 2e-5);
}

/// Magnetic Lorentz slab (`Epsilon = 1.5`, `Mue = 1.2`, magnetic
/// `f_p = 4 GHz`, `f_Lor = 8 GHz`, `τ = 0.5 ns`).
#[test]
fn lorentz_magnetic_slab() {
    check("adv_lorentz_mag_slab", 2e-5);
}

/// Two-pole material (`Order = 2`): an electric Lorentz pole, and a
/// second order with an electric and a magnetic Drude pole.
#[test]
fn lorentz_two_poles() {
    check("adv_lorentz2_slab", 2e-5);
}

/// Debye slab with faces off the mesh: `29.6 ≤ x ≤ 70.4`, `z ≤ 1.2` (the
/// slab covers the lower Ez edges and the Ex edges of the z = 1 plane by
/// their midpoints only): poles on an edge iff its midpoint is inside.
#[test]
fn debye_offgrid() {
    check("adv_debye_offgrid", 2e-5);
}

/// Filled Lorentz line on a coarse mesh (4 mm, 7 ps, `ω_0·dt = 0.33`):
/// the time discretisation matters here (trapezoidal: 5e-2 off).
#[test]
fn lorentz_coarse() {
    check("adv_lorentz_coarse", 2e-5);
}

/// The same coarse Lorentz line with the trapezoidal scheme differs by a
/// few percent: the formulation-level difference of the two schemes.
#[test]
fn lorentz_coarse_trapezoidal_differs() {
    let opts = CompileOptions {
        dispersive_scheme: ems::engine::dispersive::Scheme::Trapezoidal,
        ..CompileOptions::default()
    };
    let res = run("adv_lorentz_coarse", &opts);
    for (f, e) in compare("adv_lorentz_coarse", &res) {
        assert!(e > 1e-2 && e < 0.2, "{f}: {e}");
    }
}
